-- apprentices: 1=Alice (Apprentice, 1200), 2=Bjorn (Adept, 2400),
--              3=Cassia (Mage, 4800), 4=Dorian (Novice, 80)

-- Statement A — single-row UPDATE:
UPDATE apprentices SET xp = xp + 500 WHERE id = 1;

-- Statement B — multi-row UPDATE:
UPDATE apprentices SET rank = 'Adept' WHERE rank = 'Apprentice' AND xp >= 1000;

-- Statement C — DANGEROUS: missing WHERE.
-- Updates EVERY row.
UPDATE apprentices SET xp = 0;

-- Statement D — single-row DELETE:
DELETE FROM apprentices WHERE id = 4;

-- Statement E — DANGEROUS: missing WHERE.
-- Empties the table.
DELETE FROM apprentices;

-- Statement F — preview first (safe habit):
SELECT * FROM apprentices WHERE xp = 0;
-- Result: just Dorian if his xp was reset; nobody otherwise.
-- Then convert to a DELETE only if the SELECT result is what you want:
DELETE FROM apprentices WHERE xp = 0;

storyBeats.text:
BEGIN;
  UPDATE apprentices SET xp = xp - 100 WHERE id = 1;
  UPDATE apprentices SET xp = xp + 100 WHERE id = 2;
COMMIT;

-- If anything between BEGIN and COMMIT fails, the application calls
-- ROLLBACK; instead, and the database forgets both UPDATEs entirely.
-- Other connections never saw the in-progress state.

-- A common production pattern: BEGIN, run an UPDATE, SELECT to verify
-- the result, and only then COMMIT.
BEGIN;
  UPDATE apprentices SET xp = 0 WHERE rank = 'Novice';
  SELECT id, name, xp FROM apprentices WHERE rank = 'Novice';
  -- Eyeball the result. If wrong:
  -- ROLLBACK; (and nothing changed)
  -- If right:
COMMIT;

subChunks.guidedPracticeStarterCode:
-- Block A — succeeds end-to-end:
BEGIN;
  UPDATE apprentices SET xp = xp - 100 WHERE id = 1;
  UPDATE apprentices SET xp = xp + 100 WHERE id = 2;
COMMIT;
-- Final: id=1 has xp-100, id=2 has xp+100, both visible to others.

-- Block B — application changes its mind:
BEGIN;
  UPDATE apprentices SET xp = 0 WHERE rank = 'Novice';
  -- Realise this was wrong.
ROLLBACK;
-- Final: nothing changed. Other connections never saw the UPDATE.

-- Block C — second statement fails:
BEGIN;
  UPDATE apprentices SET xp = xp - 100 WHERE id = 1;
  -- Engine throws (e.g. constraint violation):
  UPDATE apprentices SET xp = xp + 100 WHERE id = 9999;
  -- ↑ id 9999 doesn't exist; not really an error in standard SQL,
  --   but imagine the second UPDATE fails for any reason.
-- Application catches the error and:
ROLLBACK;
-- Final: nothing changed.

-- Block D — auto-commit (no transaction):
UPDATE apprentices SET xp = xp - 100 WHERE id = 1;
-- Engine implicitly: BEGIN; <UPDATE>; COMMIT;
-- Final: id=1's xp-100 is permanent immediately.
